:root {
  --bg: #ffffff;
  --border: #e2e8f0;
  --header-bg: #1e293b;
  --header-text: #f8fafc;
  --header-sub: #94a3b8;
  --title-accent: #38bdf8;
  --total-amount: #38bdf8;
  --room-bg: #f8fafc;
  --room-name: #1e293b;
  --bar-track: #e2e8f0;
  --dot-kitchen: #f97316;
  --bar-kitchen: #f97316;
  --dot-bath: #22c55e;
  --bar-bath: #ef4444;
  --dot-living: #a78bfa;
  --bar-living: #a78bfa;
  --dot-deck: #94a3b8;
  --bar-deck: #94a3b8;
  --status-active-bg: #fef3c7;
  --status-active-text: #d97706;
  --status-done-bg: #dcfce7;
  --status-done-text: #16a34a;
  --status-pending-bg: #f1f5f9;
  --status-pending-text: #64748b;
  --spent-text: #64748b;
  --budget-text: #1e293b;
  --footer-bg: #f1f5f9;
  --footer-text: #1e293b;
  --footer-key: #64748b;
  --divider: #cbd5e1;
}

.tracker {
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: 16px;
  width: 500px;
  overflow: hidden;
}

.tracker-header {
  background: var(--header-bg);
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 14px 18px;
}

.tracker-icon {
  font-size: 28px;
  line-height: 1;
}

.tracker-title {
  flex: 1;
}

.tracker-title h2 {
  margin: 0;
  font-size: 18px;
  font-weight: 700;
  color: var(--header-text);
  line-height: 1.2;
}

.tracker-title p {
  margin: 0;
  font-size: 12px;
  color: var(--header-sub);
  line-height: 1.4;
}

.tracker-total {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
}

.total-label {
  font-size: 11px;
  color: var(--header-sub);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.total-amount {
  font-size: 20px;
  font-weight: 800;
  color: var(--total-amount);
  line-height: 1.2;
}

.rooms {
  display: flex;
  flex-direction: column;
  gap: 0px;
  padding: 10px 18px;
}

.room {
  background: var(--room-bg);
  border-radius: 10px;
  padding: 10px 12px;
  margin-bottom: 6px;
}

.room-info {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 7px;
}

.room-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  flex-shrink: 0;
}

.dot-kitchen { background: var(--dot-kitchen); }
.dot-bath    { background: var(--dot-bath); }
.dot-living  { background: var(--dot-living); }
.dot-deck    { background: var(--dot-deck); }

.room-name {
  font-size: 14px;
  font-weight: 600;
  color: var(--room-name);
  flex: 1;
}

.room-status {
  font-size: 11px;
  font-weight: 600;
  padding: 2px 8px;
  border-radius: 20px;
}

.status-active  { background: var(--status-active-bg);  color: var(--status-active-text); }
.status-done    { background: var(--status-done-bg);    color: var(--status-done-text); }
.status-pending { background: var(--status-pending-bg); color: var(--status-pending-text); }

.room-bar-wrap {
  background: var(--bar-track);
  border-radius: 999px;
  height: 8px;
  overflow: hidden;
  margin-bottom: 5px;
}

.room-bar {
  height: 100%;
  border-radius: 999px;
}

.bar-kitchen { background: var(--bar-kitchen); width: 80%; }
.bar-bath    { background: var(--bar-bath);    width: 100%; }
.bar-living  { background: var(--bar-living);  width: 24%; }
.bar-deck    { background: var(--bar-deck);    width: 0%; }

.room-amounts {
  display: flex;
  justify-content: space-between;
}

.spent {
  font-size: 11px;
  color: var(--spent-text);
}

.budget {
  font-size: 11px;
  font-weight: 600;
  color: var(--budget-text);
}

.tracker-footer {
  background: var(--footer-bg);
  display: flex;
  align-items: center;
  justify-content: space-around;
  padding: 12px 18px;
  border-top: 1px solid var(--border);
}

.footer-stat {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
}

.stat-val {
  font-size: 16px;
  font-weight: 700;
  color: var(--footer-text);
  line-height: 1.2;
}

.stat-key {
  font-size: 11px;
  color: var(--footer-key);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.footer-divider {
  width: 1px;
  height: 32px;
  background: var(--divider);
}
